package profinet

import (
	"fmt"

	"github.com/joyautomation/nautilus/internal/tagfile"
)

// DeviceTagsYAML renders the tag file for a device manifest: one tag per
// binding, with its IEC type, and the online companion. The PLC's outputs
// are nautilus inputs, its inputs nautilus outputs.
func DeviceTagsYAML(m DeviceManifest, online, tagsPath string) ([]byte, error) {
	header := []string{
		"Generated by `naut profinet tags profinet_device.yaml`: one tag per",
		"binding in the manifest. Do not edit; re-run after changing the manifest.",
		"",
		fmt.Sprintf("Compose it into a project with:  tag-files: [%s]", tagsPath),
	}
	var tags []tagfile.Tag
	for _, b := range m.Tags {
		t := tagfile.Tag{Name: b.Name, Role: "input", Type: b.format.IECType()}
		where := fmt.Sprintf("slot %d.%d byte %d", b.Slot, b.Subslot, b.Offset)
		if b.Bit != nil {
			where += fmt.Sprintf(" bit %d", *b.Bit)
		}
		if b.ToPLC() {
			t.Role = "output"
			t.Desc = "to the PLC (its input), " + where
		} else {
			t.Desc = "from the PLC (its output), " + where
		}
		tags = append(tags, t)
	}
	if online != "" {
		tags = append(tags, tagfile.Tag{Name: online, Role: "input", Type: "BOOL", Desc: "a PLC holds an AR and exchanges data with this device"})
	}
	return tagfile.Render(header, tags)
}
